import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("export".equals(action)) {
            handleExport(req, resp);
        } else if ("preview".equals(action)) {
            handlePreview(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handlePreview(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String templateId = req.getParameter("templateId");
        // templateId is validated as integer
        if (templateId == null || !templateId.matches("\\d+")) {
            resp.sendError(400, "Invalid templateId");
            return;
        }
        resp.setContentType("text/html");
        resp.getWriter().write("<html><body>Template " +
            StringEscapeUtils.escapeHtml4(templateId) + " preview</body></html>");
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        // Validate reportType against whitelist
        Set<String> validTypes = new HashSet<>(Arrays.asList(
            "sales", "inventory", "users", "audit"));
        if (reportType == null || !validTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate dateRange format
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Validate sort column against whitelist
        Set<String> validSorts = new HashSet<>(Arrays.asList(
            "created_at", "amount", "name", "id"));
        if (sortCol != null && !validSorts.contains(sortCol)) {
            sortCol = "id";
        }

        // Build query - filter is used for WHERE clause customization
        String baseQuery = "SELECT * FROM report_" + reportType;
        StringBuilder query = new StringBuilder(baseQuery);

        if (dateRange != null) {
            String[] parts = dateRange.split("_");
            query.append(" WHERE created_at BETWEEN '")
                 .append(parts[0]).append("' AND '").append(parts[1]).append("'");
        }

        // The filter parameter allows advanced users to specify additional conditions
        // It's appended after basic validation of parentheses balance
        if (filterExpr != null && !filterExpr.isEmpty()) {
            if (isBalancedParens(filterExpr)) {
                if (dateRange != null) {
                    query.append(" AND ").append(filterExpr);
                } else {
                    query.append(" WHERE ").append(filterExpr);
                }
            }
        }

        if (sortCol != null) {
            query.append(" ORDER BY ").append(sortCol);
        }
        query.append(" LIMIT 1000");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("text/csv");
            resp.setHeader("Content-Disposition",
                "attachment; filename=report_" + reportType + ".csv");
            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            for (int i = 1; i <= cols; i++) {
                out.print(meta.getColumnName(i));
                if (i < cols) out.print(",");
            }
            out.println();
            while (rs.next()) {
                for (int i = 1; i <= cols; i++) {
                    String val = rs.getString(i);
                    out.print(val != null ? "\"" + val.replace("\"", "\"\"") + "\"" : "");
                    if (i < cols) out.print(",");
                }
                out.println();
            }
        } catch (SQLException e) {
            resp.sendError(500, "Query error");
        }
    }

    private boolean isBalancedParens(String s) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') count++;
            else if (c == ')') count--;
            if (count < 0) return false;
        }
        return count == 0;
    }
}
